/* A Node-API addon for tests/npm: values, strings, errors, a class with native state, buffers,
 * a promise settled by async work, and a thread-safe function called from another thread.
 * Built with `cc -bundle -undefined dynamic_lookup` (Node-API comes from the program). */
#include <pthread.h>
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

typedef struct napi_env__ *napi_env;
typedef struct napi_value__ *napi_value;
typedef struct napi_ref__ *napi_ref;
typedef struct napi_callback_info__ *napi_callback_info;
typedef struct napi_deferred__ *napi_deferred;
typedef struct napi_async_work__ *napi_async_work;
typedef struct napi_threadsafe_function__ *napi_threadsafe_function;
typedef int napi_status;
typedef napi_value (*napi_callback)(napi_env, napi_callback_info);
typedef void (*napi_finalize)(napi_env, void *, void *);
typedef struct { const char *utf8name; napi_value name; napi_callback method, getter, setter; napi_value value; int attributes; void *data; } napi_property_descriptor;
typedef void (*napi_async_execute_callback)(napi_env, void *);
typedef void (*napi_async_complete_callback)(napi_env, napi_status, void *);
typedef void (*napi_threadsafe_function_call_js)(napi_env, napi_value, void *, void *);

napi_status napi_create_function(napi_env, const char *, size_t, napi_callback, void *, napi_value *);
napi_status napi_get_cb_info(napi_env, napi_callback_info, size_t *, napi_value *, napi_value *, void **);
napi_status napi_create_double(napi_env, double, napi_value *);
napi_status napi_get_value_double(napi_env, napi_value, double *);
napi_status napi_get_value_int32(napi_env, napi_value, int32_t *);
napi_status napi_create_string_utf8(napi_env, const char *, size_t, napi_value *);
napi_status napi_get_value_string_utf8(napi_env, napi_value, char *, size_t, size_t *);
napi_status napi_create_object(napi_env, napi_value *);
napi_status napi_set_named_property(napi_env, napi_value, const char *, napi_value);
napi_status napi_get_named_property(napi_env, napi_value, const char *, napi_value *);
napi_status napi_create_array_with_length(napi_env, size_t, napi_value *);
napi_status napi_set_element(napi_env, napi_value, uint32_t, napi_value);
napi_status napi_get_array_length(napi_env, napi_value, uint32_t *);
napi_status napi_get_element(napi_env, napi_value, uint32_t, napi_value *);
napi_status napi_throw_range_error(napi_env, const char *, const char *);
napi_status napi_define_class(napi_env, const char *, size_t, napi_callback, void *, size_t, const napi_property_descriptor *, napi_value *);
napi_status napi_wrap(napi_env, napi_value, void *, napi_finalize, void *, napi_ref *);
napi_status napi_unwrap(napi_env, napi_value, void **);
napi_status napi_define_properties(napi_env, napi_value, size_t, const napi_property_descriptor *);
napi_status napi_create_buffer_copy(napi_env, size_t, const void *, void **, napi_value *);
napi_status napi_get_buffer_info(napi_env, napi_value, void **, size_t *);
napi_status napi_create_promise(napi_env, napi_deferred *, napi_value *);
napi_status napi_resolve_deferred(napi_env, napi_deferred, napi_value);
napi_status napi_create_async_work(napi_env, napi_value, napi_value, napi_async_execute_callback, napi_async_complete_callback, void *, napi_async_work *);
napi_status napi_queue_async_work(napi_env, napi_async_work);
napi_status napi_delete_async_work(napi_env, napi_async_work);
napi_status napi_create_threadsafe_function(napi_env, napi_value, napi_value, napi_value, size_t, size_t, void *, napi_finalize, void *, napi_threadsafe_function_call_js, napi_threadsafe_function *);
napi_status napi_call_threadsafe_function(napi_threadsafe_function, void *, int);
napi_status napi_release_threadsafe_function(napi_threadsafe_function, int);
napi_status napi_call_function(napi_env, napi_value, napi_value, size_t, const napi_value *, napi_value *);
napi_status napi_get_undefined(napi_env, napi_value *);

static napi_value add(napi_env env, napi_callback_info info) {
    size_t argc = 2;
    napi_value a[2], r;
    double x, y;
    napi_get_cb_info(env, info, &argc, a, NULL, NULL);
    napi_get_value_double(env, a[0], &x);
    napi_get_value_double(env, a[1], &y);
    napi_create_double(env, x + y, &r);
    return r;
}

static napi_value greet(napi_env env, napi_callback_info info) {
    size_t argc = 1, n;
    napi_value a[1], r;
    char name[64], out[96];
    napi_get_cb_info(env, info, &argc, a, NULL, NULL);
    napi_get_value_string_utf8(env, a[0], name, sizeof name, &n);
    strcpy(out, "héllo, ");
    strcat(out, name);
    napi_create_string_utf8(env, out, (size_t)-1, &r);
    return r;
}

static napi_value describe(napi_env env, napi_callback_info info) {
    size_t argc = 1;
    napi_value a[1], r, v, list, x;
    napi_get_cb_info(env, info, &argc, a, NULL, NULL);
    napi_create_object(env, &r);
    napi_get_named_property(env, a[0], "name", &v);
    napi_set_named_property(env, r, "who", v);
    napi_get_named_property(env, a[0], "tags", &list);
    uint32_t len;
    napi_get_array_length(env, list, &len);
    napi_value rev;
    napi_create_array_with_length(env, len, &rev);
    for (uint32_t i = 0; i < len; i++) {
        napi_get_element(env, list, i, &x);
        napi_set_element(env, rev, len - 1 - i, x);
    }
    napi_set_named_property(env, r, "reversed", rev);
    return r;
}

static napi_value fail(napi_env env, napi_callback_info info) {
    (void)info;
    napi_throw_range_error(env, "ERR_TOO_BIG", "too big for C");
    return NULL;
}

/* class Counter { constructor(start), inc(), get value } with the count in C */
static void counter_free(napi_env env, void *data, void *hint) { (void)env; (void)hint; free(data); }

static napi_value counter_new(napi_env env, napi_callback_info info) {
    size_t argc = 1;
    napi_value a[1], self;
    int32_t start = 0;
    napi_get_cb_info(env, info, &argc, a, &self, NULL);
    if (argc > 0) napi_get_value_int32(env, a[0], &start);
    int32_t *n = malloc(sizeof *n);
    *n = start;
    napi_wrap(env, self, n, counter_free, NULL, NULL);
    return self;
}

static napi_value counter_inc(napi_env env, napi_callback_info info) {
    napi_value self;
    int32_t *n;
    napi_get_cb_info(env, info, NULL, NULL, &self, NULL);
    napi_unwrap(env, self, (void **)&n);
    (*n)++;
    return self;
}

static napi_value counter_value(napi_env env, napi_callback_info info) {
    napi_value self, r;
    int32_t *n;
    napi_get_cb_info(env, info, NULL, NULL, &self, NULL);
    napi_unwrap(env, self, (void **)&n);
    napi_create_double(env, *n, &r);
    return r;
}

static napi_value upper(napi_env env, napi_callback_info info) {
    size_t argc = 1, len;
    napi_value a[1], r;
    char *p;
    napi_get_cb_info(env, info, &argc, a, NULL, NULL);
    napi_get_buffer_info(env, a[0], (void **)&p, &len);
    char *copy = malloc(len + 1);
    for (size_t i = 0; i < len; i++) copy[i] = (p[i] >= 'a' && p[i] <= 'z') ? p[i] - 32 : p[i];
    napi_create_buffer_copy(env, len, copy, NULL, &r);
    free(copy);
    return r;
}

/* sumAsync(n): a promise of 1 + ... + n, computed on a worker thread */
typedef struct { napi_async_work work; napi_deferred d; double n, sum; } sum_job;

static void sum_exec(napi_env env, void *data) {
    (void)env;
    sum_job *j = data;
    for (double i = 1; i <= j->n; i++) j->sum += i;
}

static void sum_done(napi_env env, napi_status status, void *data) {
    (void)status;
    sum_job *j = data;
    napi_value r;
    napi_create_double(env, j->sum, &r);
    napi_resolve_deferred(env, j->d, r);
    napi_delete_async_work(env, j->work);
    free(j);
}

static napi_value sum_async(napi_env env, napi_callback_info info) {
    size_t argc = 1;
    napi_value a[1], promise, name;
    napi_get_cb_info(env, info, &argc, a, NULL, NULL);
    sum_job *j = calloc(1, sizeof *j);
    napi_get_value_double(env, a[0], &j->n);
    napi_create_promise(env, &j->d, &promise);
    napi_create_string_utf8(env, "sum", 3, &name);
    napi_create_async_work(env, NULL, name, sum_exec, sum_done, j, &j->work);
    napi_queue_async_work(env, j->work);
    return promise;
}

/* ticks(cb): calls cb(1), cb(2), cb(3) from another thread, through a thread-safe function */
static void tick_call(napi_env env, napi_value cb, void *context, void *data) {
    (void)context;
    napi_value arg, undef;
    napi_create_double(env, (double)(intptr_t)data, &arg);
    napi_get_undefined(env, &undef);
    napi_call_function(env, undef, cb, 1, &arg, NULL);
}

static void *tick_thread(void *arg) {
    napi_threadsafe_function f = arg;
    for (intptr_t i = 1; i <= 3; i++) napi_call_threadsafe_function(f, (void *)i, 1);
    napi_release_threadsafe_function(f, 0);
    return NULL;
}

static napi_value ticks(napi_env env, napi_callback_info info) {
    size_t argc = 1;
    napi_value a[1], name;
    napi_get_cb_info(env, info, &argc, a, NULL, NULL);
    napi_create_string_utf8(env, "ticks", 5, &name);
    napi_threadsafe_function f;
    napi_create_threadsafe_function(env, a[0], NULL, name, 0, 1, NULL, NULL, NULL, tick_call, &f);
    pthread_t t;
    pthread_create(&t, NULL, tick_thread, f);
    pthread_detach(t);
    return NULL;
}

napi_value napi_register_module_v1(napi_env env, napi_value exports) {
    napi_property_descriptor fns[] = {
        {"add", NULL, add, NULL, NULL, NULL, 0, NULL},
        {"greet", NULL, greet, NULL, NULL, NULL, 0, NULL},
        {"describe", NULL, describe, NULL, NULL, NULL, 0, NULL},
        {"fail", NULL, fail, NULL, NULL, NULL, 0, NULL},
        {"upper", NULL, upper, NULL, NULL, NULL, 0, NULL},
        {"sumAsync", NULL, sum_async, NULL, NULL, NULL, 0, NULL},
        {"ticks", NULL, ticks, NULL, NULL, NULL, 0, NULL},
    };
    napi_define_properties(env, exports, sizeof fns / sizeof *fns, fns);
    napi_property_descriptor members[] = {
        {"inc", NULL, counter_inc, NULL, NULL, NULL, 0, NULL},
        {"value", NULL, NULL, counter_value, NULL, NULL, 0, NULL},
    };
    napi_value cls;
    napi_define_class(env, "Counter", (size_t)-1, counter_new, NULL, 2, members, &cls);
    napi_set_named_property(env, exports, "Counter", cls);
    return exports;
}
